#include <iostream>
#include <cmath>
using namespace std;

long long p, q, r;

long long get_gcd(long long a, long long b) {
    while (b != 0) {
        long long temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cin >> p >> q >> r;

    if (q <= r) {
        long long g = get_gcd(p, q);
        p /= g;
        q /= g;
        cout << p << "/" << q;
        return 0;
    }
    if (p == q) {
        cout << "1/1";
        return 0;
    }

    double best_diff = 1e18;
    double ratio = double(p) / double(q);
    long long numerator, denominator;
    long long left_bound = 0, right_bound = q;
    for (long long i = 1; i <= r; ++i) {
        while (i * p > right_bound) {
            left_bound += q;
            right_bound += q;
        }
        if (i * p >= left_bound && i * p <= right_bound) {
            long long low = left_bound / q;
            long long high = right_bound / q;
            double low_ratio = double(low) / double(i);
            double high_ratio = double(high) / double(i);
            double diff_low = abs(ratio - low_ratio);
            double diff_high = abs(ratio - high_ratio);
            if (diff_high < diff_low) {
                if (diff_high < best_diff) {
                    best_diff = diff_high;
                    numerator = high;
                    denominator = i;
                }
            } else {
                if (diff_low < best_diff) {
                    best_diff = diff_low;
                    numerator = low;
                    denominator = i;
                }
            }
        }
    }
    long long g = get_gcd(numerator, denominator);
    numerator /= g;
    denominator /= g;
    cout << numerator << "/" << denominator;
    return 0;
}
